import{_ as a}from"./chunks/loaddata2dparamsv2_half_no_transpose.C1Z4tLQL.js";import{_ as n,o as p,a as l,b as t}from"./app.DKoEZOcr.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"矩阵计算（ISASI）","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_ISASI"},{"text":"矩阵计算的搬入","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_load/cube_compute_load"},{"text":"LoadData（GMToL1-2D矩阵搬运V2）","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_load/LoadData_GMToL1_2DV2"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_load/LoadData_GMToL1_2DV2.md","filePath":"api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_load/LoadData_GMToL1_2DV2.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"数据类型","slug":"数据类型","link":"#数据类型"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788159000000}'),c={name:"api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_load/LoadData_GMToL1_2DV2.md"};function e(i,s,o,d,r,h){return p(),l("div",null,[...s[0]||(s[0]=[t(`<div><article class="markdown-body"><h1>LoadData（GMToL1-2D矩阵搬运V2）<a id="ZH-CN_TOPIC_0000002594327301"></a></h1><h2 id="产品支持情况">产品支持情况<a id="section1550532418810"></a><a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：不支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：不支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><div data-filter="x90"><ul><li>Kirin X90：不支持</li></ul></div><div data-filter="9030"><ul><li>Kirin 9030：不支持</li></ul></div><h2 id="功能说明">功能说明<a id="section618mcpsimp"></a><a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>&quot;basic_api/kernel_operator_mm_intf.h&quot;</code>。</p><p>负责完成普通矩阵计算所需的2D格式数据的搬运，以大小为512字节的数据分形为单位从Global Memory搬运至L1 Buffer（TPosition为A1/B1）。</p><h2 id="函数原型">函数原型<a id="section620mcpsimp"></a><a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">LoadData</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">GlobalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">LoadData2DParamsV2</span><span class="o">&amp;</span><span class="w"> </span><span class="n">loadDataParams</span><span class="p">)</span>
</code></pre></div><h2 id="参数说明">参数说明<a id="section622mcpsimp"></a><a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table><thead><tr><th>参数名称</th><th>含义</th></tr></thead><tbody><tr><td>T</td><td>源操作数和目的操作数的数据类型。</td></tr></tbody></table><p><strong>表 2</strong> 通用参数说明</p><table><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>dst</td><td>输出</td><td>目的操作数，类型为LocalTensor。支持的物理存储位置为L1 Buffer（TPosition为A1/B1）。<br>数据分形无格式要求，一般情况下为NZ格式。NZ格式下，对应的分形大小为16 * (32字节 / sizeof(T))。</td></tr><tr><td>src</td><td>输入</td><td>源操作数，类型为GlobalTensor。数据类型需要与dst保持一致。</td></tr><tr><td>loadDataParams</td><td>输入</td><td>LoadData参数结构体，类型为LoadData2DParamsV2，具体参考<a href="#table49630346128">表3</a>。</td></tr></tbody></table><p><strong>表 3</strong> LoadData2DParamsV2结构体内参数说明<a id="table49630346128"></a></p><table><thead><tr><th>参数名称</th><th>含义</th></tr></thead><tbody><tr><td>mStartPosition</td><td>以M*K矩阵为例，源矩阵M轴方向的起始位置，单位为16个元素。</td></tr><tr><td>kStartPosition</td><td>以M*K矩阵为例，源矩阵K轴方向的起始位置，单位为32字节。</td></tr><tr><td>mStep</td><td>以M*K矩阵为例，源矩阵M轴方向搬运长度，单位为16个元素。取值范围：mStep∈[0, 255]。<br><strong>注：mStep=0表示不执行搬运，该接口将被视为NOP（空操作）。</strong></td></tr><tr><td>kStep</td><td>以M*K矩阵为例，源矩阵K轴方向搬运长度，单位为32字节。取值范围：kStep∈[0, 255]。<br><strong>注：kStep=0表示不执行搬运，该接口将被视为NOP（空操作）。</strong></td></tr><tr><td>srcStride</td><td>以M*K矩阵为例，源矩阵K方向前一个分形起始地址与后一个分形起始地址的间隔，单位为512字节。</td></tr><tr><td>dstStride</td><td>以M*K矩阵为例，目的矩阵K方向前一个分形起始地址与后一个分形起始地址的间隔，单位为512字节。</td></tr><tr><td>ifTranspose</td><td>是否启用转置功能，对每个分形矩阵进行转置，默认为false。<br>  • true：启用。<br>  • false：不启用。<br>注意：本通路场景下（GM-&gt;L1 Buffer）不支持转置，参数无意义，保持默认值即可。</td></tr><tr><td>sid</td><td>预留参数，配置为0即可。</td></tr></tbody></table><p>LoadData2DParamsV2结构体在不启用转置时，示意图如下，参数设置值和解释说明如下：</p><ul><li>mStartPosition = 2，表示源矩阵M轴方向的起始位置为第32个元素（2*16个元素）。</li><li>kStartPosition = 2，表示源矩阵K轴方向的起始位置为第32个元素（2*32字节）。</li><li>mStep = 2，表示源矩阵M轴方向搬运长度为32个元素（2*16个元素）。</li><li>kStep = 3，表示源矩阵K轴方向搬运长度为48个元素（3*32字节）。</li><li>srcStride = 5，表示源矩阵K方向前一个分形起始地址与后一个分形起始地址的间隔为1280个元素（5*512字节）。</li><li>dstStride = 3，表示目的矩阵K方向前一个分形起始地址与后一个分形起始地址的间隔为768个元素（3*512字节）。</li><li>ifTranspose = false，表示不启用转置。</li><li>sid = 0，预留参数，配置为0即可。</li></ul><p><strong>图 1</strong> LoadData2DParamsV2结构体参数示例（以half数据类型，不启用转置为例）<a id="fig13901164574218"></a></p><p><img src="`+a+`" alt></p><h2 id="数据类型">数据类型<a id="section4219135304818"></a><a class="header-anchor" href="#数据类型">​</a></h2><p>支持数据类型为：uint8_t、int8_t、fp4x2_e2m1_t、fp4x2_e1m2_t、hifloat8_t、fp8_e5m2_t、fp8_e4m3fn_t、half、bfloat16_t、uint32_t、int32_t、float。</p><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="约束说明">约束说明<a id="section633mcpsimp"></a><a class="header-anchor" href="#约束说明">​</a></h2><ul><li>操作数地址对齐要求请参见<a href="../../../general_description_and_constraints.html#section796754519912">通用地址对齐约束</a>。</li><li>本通路场景下不支持转置。</li></ul><h2 id="调用示例">调用示例<a id="section6461234123118"></a><a class="header-anchor" href="#调用示例">​</a></h2><p>以<a href="#fig13901164574218">图 1</a>所示的场景为例，源矩阵为GM上Nz排布的half数据，从M轴第2个分形、K轴第2个32B块开始，搬运2个M方向分形、3个K方向32B块到L1 Buffer。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">fractalElemCount</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">256</span><span class="p">;</span>
<span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">srcElemCount</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">25</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">fractalElemCount</span><span class="p">;</span>
<span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">dstElemCount</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">9</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">fractalElemCount</span><span class="p">;</span>

<span class="c1">// 源操作数：GM上按Nz分形排布存放half数据。一个512B分形包含256个half。</span>
<span class="c1">// GM shape为80 * 80，M方向和K方向各有5个小分形，因此预留5 * 5 = 25个512B分形。</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">GlobalTensor</span><span class="o">&lt;</span><span class="n">half</span><span class="o">&gt;</span><span class="w"> </span><span class="n">srcGm</span><span class="p">;</span>
<span class="n">srcGm</span><span class="p">.</span><span class="n">SetGlobalBuffer</span><span class="p">((</span><span class="n">__gm__</span><span class="w"> </span><span class="n">half</span><span class="w"> </span><span class="o">*</span><span class="p">)</span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="n">srcElemCount</span><span class="p">);</span>

<span class="c1">// 目的操作数：L1 Buffer，目的矩阵为3 * 3个小分形，因此预留9个512B分形。</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">half</span><span class="o">&gt;</span><span class="w"> </span><span class="n">dstLocal</span><span class="p">(</span><span class="n">AscendC</span><span class="o">::</span><span class="n">TPosition</span><span class="o">::</span><span class="n">A1</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="n">dstElemCount</span><span class="p">);</span>

<span class="n">AscendC</span><span class="o">::</span><span class="n">LoadData2DParamsV2</span><span class="w"> </span><span class="n">loadDataParams</span><span class="p">;</span>
<span class="c1">// 源矩阵M轴起始位置为第32个元素，即2 * 16个元素。</span>
<span class="n">loadDataParams</span><span class="p">.</span><span class="n">mStartPosition</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">2</span><span class="p">;</span>
<span class="c1">// 源矩阵K轴起始位置为第32个half，即2 * 32B。</span>
<span class="n">loadDataParams</span><span class="p">.</span><span class="n">kStartPosition</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">2</span><span class="p">;</span>
<span class="c1">// M方向搬运32个元素，即2 * 16个元素。</span>
<span class="n">loadDataParams</span><span class="p">.</span><span class="n">mStep</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">2</span><span class="p">;</span>
<span class="c1">// K方向搬运48个half，即3 * 32B。</span>
<span class="n">loadDataParams</span><span class="p">.</span><span class="n">kStep</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">3</span><span class="p">;</span>
<span class="c1">// GM源矩阵M方向有5个小分形。</span>
<span class="n">loadDataParams</span><span class="p">.</span><span class="n">srcStride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">5</span><span class="p">;</span>
<span class="c1">// 目的A1矩阵M方向有3个小分形。</span>
<span class="n">loadDataParams</span><span class="p">.</span><span class="n">dstStride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">3</span><span class="p">;</span>
<span class="c1">// 不启用转置。</span>
<span class="n">loadDataParams</span><span class="p">.</span><span class="n">ifTranspose</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="nb">false</span><span class="p">;</span>
<span class="c1">// 预留参数，固定配置为0。</span>
<span class="n">loadDataParams</span><span class="p">.</span><span class="n">sid</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span>

<span class="n">AscendC</span><span class="o">::</span><span class="n">LoadData</span><span class="p">(</span><span class="n">dstLocal</span><span class="p">,</span><span class="w"> </span><span class="n">srcGm</span><span class="p">,</span><span class="w"> </span><span class="n">loadDataParams</span><span class="p">);</span>
</code></pre></div></article></div>`,1)])])}const f=n(c,[["render",e]]);export{u as __pageData,f as default};
